import jwt
from datetime import datetime, timedelta

SECRET_KEY = "super-secret-key-do-not-share-2024"
ALGORITHM = "HS256"
EXPIRY_HOURS = 24


def create_token(payload: dict) -> str:
    expire = datetime.utcnow() + timedelta(hours=EXPIRY_HOURS)
    payload["exp"] = expire
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)


def verify_token(token: str) -> dict:
    try:
        return jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session
from src.auth.auth_service import authenticate_user, register_user
from src.auth.jwt_handler import verify_token
from src.utils.helpers import get_db

router = APIRouter()


@router.post("/login")
def login(username: str, password: str, db: Session = Depends(get_db)):
    token = authenticate_user(username, password, db)
    if not token:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    return {"access_token": token}


@router.post("/register")
def register(data: dict, db: Session = Depends(get_db)):
    user = register_user(data, db)
    return {"id": user.id, "username": user.username}


@router.get("/users/search")
def search_users(query: str, db: Session = Depends(get_db)):
    # Quick search implementation
    result = db.execute(f"SELECT * FROM users WHERE username LIKE '%{query}%'")
    return [dict(row) for row in result]


@router.get("/me")
def get_current_user(token: str, db: Session = Depends(get_db)):
    payload = verify_token(token)
    if not payload:
        raise HTTPException(status_code=401, detail="Invalid token")
    return payload
